namespace sv_f6da84a05ff549c8b1ac3d4eb7582f6d.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

public class ThemeInfo
{
    public ThemeMode Mode { get; set; } = ThemeMode.System;
    public string AccentColor { get; set; } = "#0d6efd";
}

using Microsoft.AspNetCore.Components;

namespace sv_f6da84a05ff549c8b1ac3d4eb7582f6d.Services;

/// <summary>
/// Scoped service that owns the current theme state for a circuit.
/// Mutate via SetTheme/SetAccentColor, which push updates to all
/// [CascadingParameter] subscribers via CascadingValueSource.
/// </summary>
public class ThemeService
{
    private readonly CascadingValueSource<ThemeInfo> _source;
    private ThemeInfo _current;

    public ThemeService(CascadingValueSource<ThemeInfo> source)
    {
        _source = source;
        _current = new ThemeInfo();
    }

    public ThemeMode Mode => _current.Mode;
    public string AccentColor => _current.AccentColor;

    public event Action? OnChange;

    public async Task SetThemeAsync(ThemeMode mode)
    {
        _current.Mode = mode;
        await NotifyAsync();
    }

    public async Task SetAccentColorAsync(string color)
    {
        _current.AccentColor = color;
        await NotifyAsync();
    }

    public async Task SetAllAsync(ThemeMode mode, string accentColor)
    {
        _current.Mode = mode;
        _current.AccentColor = accentColor;
        await NotifyAsync();
    }

    private async Task NotifyAsync()
    {
        await _source.NotifyChangedAsync(_current);
        OnChange?.Invoke();
    }
}

@rendermode InteractiveServer
@inject ThemeService ThemeSvc
@implements IDisposable

<span class="theme-indicator" title="Current theme">
    @GetIcon() @ThemeSvc.Mode
    <span class="accent-swatch" style="background-color: @ThemeSvc.AccentColor;"></span>
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeSvc.OnChange += OnThemeChanged;
    }

    private void OnThemeChanged() => InvokeAsync(StateHasChanged);

    private string GetIcon() => ThemeSvc.Mode switch
    {
        ThemeMode.Light => "☀️",
        ThemeMode.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeSvc.OnChange -= OnThemeChanged;
    }
}

.theme-indicator {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    font-size: 0.85rem;
    padding: 0.25rem 0.6rem;
    border-radius: 0.375rem;
    background-color: rgba(0, 0, 0, 0.05);
}

.accent-swatch {
    display: inline-block;
    width: 14px;
    height: 14px;
    border-radius: 50%;
    border: 1px solid rgba(0, 0, 0, 0.15);
}

@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeSvc

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-3" style="max-width: 500px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="mb-3">
            <label class="form-label">Mode</label>
            <select class="form-select" value="@ThemeSvc.Mode" @onchange="OnModeChanged">
                @foreach (var mode in Enum.GetValues<ThemeMode>())
                {
                    <option value="@mode">@mode</option>
                }
            </select>
        </div>

        <div class="mb-3">
            <label class="form-label">Accent Color</label>
            <div class="d-flex align-items-center gap-2">
                <input type="color" class="form-control form-control-color"
                       value="@ThemeSvc.AccentColor" @onchange="OnColorChanged" />
                <span class="text-muted">@ThemeSvc.AccentColor</span>
            </div>
        </div>

        <div class="alert alert-info mb-0">
            Navigate to any page — the header indicator updates instantly
            and the theme persists across enhanced navigation.
        </div>
    </div>
</div>

@code {
    private async Task OnModeChanged(ChangeEventArgs e)
    {
        if (Enum.TryParse<ThemeMode>(e.Value?.ToString(), out var mode))
        {
            await ThemeSvc.SetThemeAsync(mode);
        }
    }

    private async Task OnColorChanged(ChangeEventArgs e)
    {
        var color = e.Value?.ToString();
        if (!string.IsNullOrWhiteSpace(color))
        {
            await ThemeSvc.SetAccentColorAsync(color);
        }
    }
}

